-- GENERATED by `wfj generate` from data/gossip/gossip-98.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["9804acdb7d0a1b15"] = { "Non così in fretta, <giovanotto/signorina>... Non affiderò le redini di un possente montone a qualcuno che non sia un alleato provato dei nani di ⟦Ironforge=Forgiardente⟧. Quando avrai raggiunto il livello Osannato con ⟦Ironforge=Forgiardente⟧, ti mostrerò volentieri le varietà di montoni che ho in vendita.", "." },
  ["980672c1bfc0c15f"] = { "Non importa. Aiutarmi è stata una follia, e ora la pagherai!", "." },
  ["980cb689406c9bd8"] = { "Parla con Idraxis.", "." },
  ["98135c7392e504ee"] = { "Non fare del male a Betsy, <cattivone/cattivona>!", "." },
  ["98146ba46410b819"] = { "SQUAWK! Polly vuole spaccarti!", "." },
  ["9818e04aa3072601"] = { "Ho visto un troll di nome ⟦Lau'Tiki=Lau'tiki⟧ pescare giù a sud, alla ⟦Darkspear Strand=Riva dei Lanciascura⟧. È proprio alla periferia del ⟦Sen'jin Village=Villaggio di Sen'jin⟧.", "." },
  ["981f90adcb2efe88"] = { "Avranno anche cacciato via tutti gli altri contadini, ma i Saldean non lasceranno mai le ⟦Westfall=Marche Occidentali⟧.", "." },
  ["98223f5fff687428"] = { "La forma fisica di %s si indebolisce. Noti che la Pietra del Vincolo vicino alla creatura brilla! Colpisci ora!", "." },
  ["98243b281a72ab9b"] = { "Quando la ⟦Darkmoon Faire=Fiera di Lunacupa⟧ sarà aperta, si troverà nella ⟦Elwynn Forest=Foresta di Elwynn⟧. Pianteremo le tende appena a sud di ⟦Goldshire=Borgodoro⟧!", "." },
  ["98267f651a98649e"] = { "Chi osa avvicinarsi a questo calderone? Assaggia la mia lama oscura!", "." },
  ["98290fe7175a4ebe"] = { "Ooh, una locanda, eh? Beh, non c'è niente di meglio della ⟦Thunderbrew Distillery=Distilleria Birratuono⟧. Riposati pure se devi, ma fatti una birra o due mentre sei lì.", "." },
  ["982a451976cd378b"] = { "%s svanisce nella nebbia...", "." },
  ["983b8aa298e1ee44"] = { "Zanza sa creare gli antichi incantamenti troll, con i componenti giusti. Questa magia ti aiuterà a sconfiggere Hakkar e i suoi servitori.\n\nTi chiedo solo di portarmi due oggetti.", "." },
  ["98427f70eb358f26"] = { "Cos'è la Brotherhood of the Light? Be'... In fondo siamo tutti membri dell'⟦Argent Dawn=Alba d'Argento⟧: membri dell'⟦Argent Dawn=Alba d'Argento⟧ che non sono frenati da morale, sensi di colpa e inutili emozioni umane. Pensa a noi come alla ⟦Scarlet Crusade=Crociata Scarlatta⟧, meno la stupidità, la mancanza di guida e il fanatismo cieco.\n\nNon lasciare che il Comandante Scarlatto ti dica il contrario.\n\nE non far sapere a Tyrosus che l'ho detto... Sarebbe un vero peccato se dovessi mutilarlo brutalmente nel caso scoppiasse una rissa.", "." },
  ["98433eb26c3e81cb"] = { "Grazie, {name}. E buona fortuna!", "." },
  ["9843d68db9b899d1"] = { "Duke of Fathoms! Ho il tuo sigillo! Rispondi alla mia chiamata!", "." },
  ["9847dfe683b5db3d"] = { "Trovo che il fondale dell'oceano sia molto tranquillo.", "." },
  ["984eb1ce228d2cb6"] = { "Questo posto sarà la tua tomba.", "." },
  ["9853567326dfb92c"] = { "Dolore delizioso.", "." },
  ["985d7ccf33775f49"] = { "Questo mi risparmierà di sicuro un po' di lavoro.", "." },
  ["985e0f4ee0edf781"] = { "%s si abbevera alla sofferenza dei caduti.", "." },
  ["985ec21bf3725b8c"] = { "Direi che è tutto. Abbiamo tutte le Lacrime di Arthas necessarie. Prova a chiedere in giro. Qualcuno degli altri avrà di sicuro qualcosa che deve ancora raccogliere per lo sforzo bellico.", "." },
  ["986a30384407f0a9"] = { "Uno splendido Winter's Veil a te... ehm... <piccolo/piccola> <bambino/bambina>. I bambini buoni ricevono speciali, ehm, sconti da qualsiasi venditore della Masseria Buongusto. Gnam.", "." },
  ["986a67f65087e1b7"] = { "Ho perso il mio ⟦Cloak of Unending Life=Mantello della Vita Eterna⟧. Puoi sostituirmelo?", "." },
  ["986df701b08f52a6"] = { "Mettici più olio di gomito, <ragazzo/ragazza>. Lavoro duro e determinazione, così si fa! Non dare retta a chi ti dice che basta studiare sui libri.", "." },
  ["9874d1927de38b2f"] = { "Non è colpa mia! Lo giuro!", "." },
  ["9878dcf121514972"] = { "Ma sei fuori di testa? Lo sai che razza di bestie abitano quel posto? Il peggio che può succedere è che dovremo raccogliere i tuoi resti con una pala. Abbiamo perso dei bravi nani per colpa di quei mostri orribili.\n\nQuindi la risposta è no. Se proprio vuoi arrivare alla ⟦Searing Gorge=Gorgia Rovente⟧, dovrai trovare un'altra strada.", "." },
  ["987f4f82472ea873"] = { "Va bene, allora, {name}. Vedo che hai capito i tuoi errori e sei <tornato/tornata> nell'ovile degli ingegneri.\n\nDivertiti con il tuo yeti!!!", "." },
  ["9881ac00cd0d1c6b"] = { "Dov'è l'anziano Totem Truce?", "." },
  ["9882698b5d57dd19"] = { "Ho dei campioni ottimi, Hornizz. Mi metto subito al lavoro. Puoi occuparti tu del resto?", "." },
  ["9886e8adbc5c74b2"] = { "La piaga del Flagello è quasi al punto di svolta: ancora qualche calderone sabotato e ce la faremo! Assicurati di fare la tua parte!", "." },
  ["9887d85727bd54ec"] = { "Salute, {class}. Sono Rexxar, campione dell'⟦Horde=Orda⟧, servitore di Thrall, signore delle bestie selvagge.", "." },
  ["988ac7f632b5f98b"] = { "%s si ricompone.", "." },
  ["9891b899407e3873"] = { "Gattino in vendita, cerca una buona casa.", "." },
  ["989402d264000557"] = { "Hai ancora delle lezioni da imparare prima che possa iniziare il tuo addestramento. Nel frattempo, forse Vhan, a ⟦Thunder Bluff=Picco del Tuono⟧, può aiutarti.", "." },
  ["989428ddc432f0f3"] = { "Una mano a un poveraccio?", "." },
  ["9896b038b64c1e30"] = { "Jin'rokh, ho perso la mia ⟦Zandalar Freethinker's Belt=Cintura del Libero Pensatore degli Zandalari⟧. Puoi aiutarmi?", "." },
  ["989a5805b147ac12"] = { "Cerca la locandiera Grishka nella ⟦Valley of Strength=Valle della Forza⟧. La sua locanda è sul lato est, a nord delle porte principali della città.", "." },
  ["98a0f8ddbfb8483d"] = { "Bah! Ora famiglio mangiare te!", "." },
  ["98a679d7103f5b90"] = { "Non accadrà MAI. Noi siamo legione. Siamo uniti. Dove sono i tuoi eroi? Vol'jin siede al sicuro accanto al giovane Capoguerra, ignaro. Zul'jin scomparso, probabilmente morto.", "." },
  ["98a9eb16489cd4e9"] = { "Aspetta... hai sentito? Qualcosa si avvicina da ovest!", "." },
  ["98aaa6ce83f285f1"] = { "Una seconda testa mi serve quanto perdere la prima.", "." },
  ["98abe273952c7381"] = { "Toglietemi {name} di dosso!", "." },
  ["98adb720fa298413"] = { "I troll Zandalari hanno viaggiato a lungo e sofferto molto per raggiungere questo luogo, ma non fare nulla... significa invocare la nostra rovina...", "." },
  ["98b6d49dcc1413df"] = { "La banca più vicina è The Vault, a ⟦Ironforge=Forgiardente⟧, <ragazzo/ragazza>.", "." },
  ["98b8095c7075620a"] = { "Cosa dovrei sacrificare?", "." },
  ["98ba611f0e4a04a9"] = { "Hai già le termiti, {name}? Sono sicuro che per <un/una> {class} in gamba come te sia una cosa ovvia.\n\nQuando ne avremo abbastanza, faremo in modo che nessuno possa più usare la segheria!", "." },
  ["98bbbff0f97b3262"] = { "Scommetto che non ti aspettavi di trovarmi in questa grotta, vero?\n\nMi chiamo J.D., e non posso dirti molto su come mi ritrovo qui, ma quello che posso dirti è che ora questa grotta è casa mia!\n\nPasso il tempo a studiare gli strani cristalli che si trovano in tutto il cratere.", "." },
  ["98c24a76216885eb"] = { "Ecco fatto: ora puoi fabbricare una ⟦Camp Chair=Sedia da Campo⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", "." },
  ["98c5370b9c5b8539"] = { "<Prendi questo libro per il bene di Azeroth!>", "." },
  ["98d3b7fc1256385d"] = { "Oh... sei di quel genere. Beh, Maximillian è l'unico da queste parti che sa qualcosa delle arti oscure. Probabilmente lo trovi al buio, nello scantinato della Locanda del Fiero Leone.", "." },
  ["98d5413c75fc6f0a"] = { "L'anziano Tiarafredda si trova alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "." },
  ["98db2a49fd80b6aa"] = { "Mi dispiace, ma non posso addestrare altri apprendisti. Cerca Mak a ⟦Thunder Bluff=Picco del Tuono⟧. Saprà insegnarti le basi.", "." },
  ["98db4308c463b667"] = { "Unisciti a noi!", "." },
  ["98e07503f9c8ca10"] = { "I montoni indigeni di Alterac sono vitali per il funzionamento della nostra cavalleria!", "." },
  ["98e2452083bf8c94"] = { "Non interrompermi.", "." },
  ["98e3d2c218fea9b9"] = { "Mi spiace, <ragazzo/ragazza>, ma non hai le basi per imparare ciò che ho da insegnare. Ma non preoccuparti, va' a parlare con il mio allievo Rotgath, lui ti darà una mano.", "." },
  ["98ed4bc9dc09155e"] = { "Immagino tu sia qui per imparare a usare una nuova arma? Sbrigati, ho molto da fare!", "." },
  ["98ef179cac98cf7e"] = { "Anya Maulray, alla locanda sull'anello superiore del ⟦Trade Quarter=Quartiere del Commercio⟧.", "." },
  ["98efb7d722a0e13c"] = { "Pare che restino solo $2113w giorni di pesca prima che tutto 'sto materiale bellico venga spedito nel deserto di ⟦Silithus=Silitus⟧, amico. Poi lo prepareranno per bene, e qualcuno dovrà suonare quel gong giù a sud della ⟦Cenarion Hold=Fortezza Cenariana⟧ per aprire i cancelli e dare inizio alla guerra.", "." },
  ["98f98ae31223a7be"] = { "Ti ridurrò in polvere e ti spazzerò nell'oblio!", "." },
})
